(()=>{const assets=["data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,"];
let timer=0,stop=null;window.custiaUniformStop=()=>{clearTimeout(timer);if(stop)stop();stop=null};
window.custiaUniformDraw=(host,play,stopAudio)=>{window.custiaUniformStop();stop=stopAudio;let frame=1,busy=false;const scene=document.createElement('div');scene.className='uniform950';const bg=new Image();bg.src=assets[0];bg.alt='';const btn=document.createElement('button');btn.type='button';btn.className='uniform950-fold';const im=new Image();im.draggable=false;btn.append(im);const status=document.createElement('p');status.className='i93notice';status.setAttribute('aria-live','polite');const reset=document.createElement('button');reset.type='button';reset.textContent='Fold again';reset.hidden=true;const controls=document.createElement('div');controls.className='i93nav';controls.append(reset);scene.append(bg,btn);host.append(scene,status,controls);const pre=assets.slice(1).map(src=>{const i=new Image();i.src=src;return i});function show(){im.src=assets[frame];im.alt=frame<=4?'Uniform shirt':'Uniform trousers';btn.setAttribute('aria-label','Fold '+im.alt);status.textContent=(frame<=4?'Shirt':'Trousers')+' · '+((frame-1)%4)+' / 3';}function wait(fn,ms){timer=setTimeout(()=>{if(scene.isConnected)fn()},ms)}btn.onclick=()=>{if(busy||frame===9)return;play();frame++;show();if(frame!==4&&frame!==8)return;busy=true;btn.disabled=true;wait(()=>{btn.classList.add('fading');wait(()=>{if(frame===4){frame=5;show();btn.classList.remove('fading');busy=false;btn.disabled=false}else{frame=9;status.textContent='Uniform folded';reset.hidden=false}},500)},350)};reset.onclick=()=>{clearTimeout(timer);stopAudio();frame=1;busy=false;btn.disabled=false;btn.classList.remove('fading');reset.hidden=true;show()};show()};})();